library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;entity Prob_6_38b_Updown_vhdl (OUT: out bit_vector (3 downto 0); 	IN: in bit_vector (3 downto 0); s1, s0, CLK: in bit); end  Prob_6_38b_Updown_;architecture Behavioral of Prob_6_38b_Updown_vhdl isbegin  process (CLK) begin  case (s1 & s0) is     when "00" =>	OUT <= OUT + "0001";     when "01" =>	OUT <= OUT Ð "0001";     when "10" =>	OUT <= IN;     when "11" =>	OUT <= OUT;  end case;  end Behavioral